/**
 * THE Salaryman art bible.
 *
 * Every piece of in-game art (offices, bathrooms, props, buildings,
 * characters, UI illustrations) is generated by Nano Banana and styled
 * through the helpers in this file. There is intentionally ONE style
 * description — change it here and the entire game's look re-bakes.
 *
 * Style: Minx City — neon-noir cyberpunk, low-saturation, isometric
 * pixel-art office aesthetic. Chunky 8-bit colour blocking, soft pink
 * (#f472b6) and cyan (#22d3ee) rim light, deep navy/black ambient
 * (#06070b → #1a1f2c), CRT scanlines suggested but not literal,
 * fluorescent overhead fill, subtle dithering. Think: PS1-era office
 * sim meets BLAME!.
 */

import { generateImage, type AspectRatio, type GenerateImageResult, type Resolution } from "./nano-banana";

export const SALARYMAN_STYLE = [
  "Salaryman game art style: isometric pixel-art, neon-noir cyberpunk corporate aesthetic.",
  "Low-saturation palette of deep navy (#06070b, #11141b, #1a1f2c) with hot pink (#f472b6) and cyan (#22d3ee) rim lights and signage glow.",
  "Chunky 8-bit colour blocking, crisp pixel edges, subtle dithering, no anti-aliasing on hard edges.",
  "Fluorescent overhead fill light from above, soft volumetric haze, CRT-monitor mood without literal scanlines.",
  "Clean composition, generous negative space, single subject centred on a flat dark background unless otherwise specified.",
  "PS1-era office sim meets BLAME!. No text, no watermarks, no UI overlays.",
].join(" ");

/** Compose the final Nano Banana prompt for a Salaryman asset. */
export function composeSalarymanPrompt(subject: string, extras?: string): string {
  return [subject.trim(), extras?.trim(), SALARYMAN_STYLE].filter(Boolean).join(" ");
}

export interface SalarymanArtOptions {
  aspectRatio?: AspectRatio;
  resolution?: Resolution;
  extras?: string;
  timeoutMs?: number;
}

/** Generate one piece of Salaryman art end-to-end (synchronous wrapper). */
export function generateSalarymanArt(subject: string, opts: SalarymanArtOptions = {}): Promise<GenerateImageResult> {
  return generateImage({
    prompt: composeSalarymanPrompt(subject, opts.extras),
    aspectRatio: opts.aspectRatio ?? "1:1",
    resolution: opts.resolution ?? "1K",
    outputFormat: "jpg",
    timeoutMs: opts.timeoutMs,
  });
}

// ── The Art Kit ────────────────────────────────────────────────────────────
// Predefined assets that the game pulls from /api/art/asset/:key.
// Add a key here, restart, and Nano Banana will bake it on first request.
//
// Categories:
//   scene     — full background scenes (16:9)
//   prop      — single objects centred on dark/empty bg (1:1)
//   building  — isometric buildings for the world map (4:3)
//   character — characters, 3/4 view portrait (3:4)
//   ui        — illustrations for menus / cards (16:9 or 1:1)

export type ArtCategory = "scene" | "prop" | "building" | "character" | "ui";

export interface ArtKitEntry {
  key: string;
  category: ArtCategory;
  subject: string;          // what to draw (style is appended automatically)
  aspectRatio: AspectRatio;
}

